var LEGZ0=HUDZ.legend, LEGMW=0;   // v27.26 (feedleg): the compact controls list zoom as set, and its width at zoom 1 as last drawn
// v16.xx (legend1), the HUD spec (2026-10-15, decision 6 and step 6): THE CONTROLS LIST LEAVES THE PLAY SPACE. The compact list (the one a new
// player has up for his first raids) stood on the vitals beside the feed, which put the biggest box on the screen in the field beside the
// character, teaching what a player learns in half a minute. It now shows for the first LEGEND_T0 seconds of a raid, while F1 is held, and
// for LEGEND_T1 seconds after F1 is pressed; the rest of the time the one line hint (F1 controls) stands over the feed in its place. F1 on a
// list that is not up brings it back (it does not step on to the full list); F1 on a list that is up cycles as it always did.
var LEGEND_T0=45, LEGEND_T1=12;
function legendUp(){ var t=(G&&G.t)||0; return t<LEGEND_T0||(t-((G&&G.legendT)||-999)<LEGEND_T1); }
function legendHint(){
  var y=(FEEDBOX.on?FEEDBOX.y-LH(6):(HUDBOX.body?HUDBOX.body.y-LH(6):H-14));
  ctx.font=FS(TYPE.micro); ctx.textAlign='left'; ctx.fillStyle='rgba(140,152,163,.55)';
  if(!(PAD&&PAD.on)) ctx.fillText(legendKeys('F1')+'  controls',14,y);
}

