{v:'VER',what:'the HUD spec: the compact controls list is up for the first 45 seconds of a raid, while F1 is held and for 12 seconds after F1, and otherwise the one line hint stands in its place, so the play space beside the player is clear',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame||!window.__textTrace) return 'SKIP: no raid here';
   if(typeof legendUp!=='function') return 'this build keeps the controls list up all raid';
   var bad=[], g, tr, i, k0=keys;
   function frames(){ for(var j=0;j<3;j++) __frame(0.016); }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={}; g.legendOn=1; g.legendT=-999;
     g.t=10; frames();
     if(!(HUDBOX.legend&&HUDBOX.legend.w>0)) bad.push('the controls list is not up at 10 s');
     g.t=60; frames();
     if(HUDBOX.legend&&HUDBOX.legend.w>0) bad.push('the controls list is still up at 60 s');
     tr=__textTrace(function(){ __frame(0.016); });
     if(!tr.some(function(e){ return /controls\s*$/.test(e.t); })) bad.push('the one line controls hint is not drawn in its place');
     g.legendT=g.t; frames();
     if(!(HUDBOX.legend&&HUDBOX.legend.w>0)) bad.push('F1 does not bring the list back');
     g.t=g.legendT+20; frames();
     if(HUDBOX.legend&&HUDBOX.legend.w>0) bad.push('the list stays up 20 s after F1');
     keys={F1:true}; frames();
     if(!(HUDBOX.legend&&HUDBOX.legend.w>0)) bad.push('the list is not up while F1 is held');
     keys={}; frames();
     if(HUDBOX.legend&&HUDBOX.legend.w>0) bad.push('the list stays up after F1 is let go');
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ keys={}; try{ var g2=__state(); if(g2&&!g2.over){ g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
